import uuid
from datetime import datetime

class ProductService:
    """
    ProductService managed product lifecycle and inventory logic.
    Used for testing automated AI test generation for Python.
    """
    def __init__(self):
        self.products = {}
        # Simple categories for validation
        self.categories = ["ELECTRONICS", "BOOKS", "CLOTHING", "HOME", "BEAUTY"]

    def add_product(self, name, category, price, stock):
        if not name or len(name) < 2:
            raise ValueError("Invalid product name")

        category = category.upper()
        if category not in self.categories:
            raise ValueError(f"Category {category} not supported")

        if price <= 0:
            raise ValueError("Price must be greater than zero")

        if stock < 0:
            raise ValueError("Stock cannot be negative")

        product_id = str(uuid.uuid4())[:8]
        product = {
            "id": product_id,
            "name": name,
            "category": category,
            "price": float(price),
            "stock": int(stock),
            "created_at": datetime.now().isoformat()
        }

        self.products[product_id] = product
        return product

    def update_stock(self, product_id, quantity):
        if product_id not in self.products:
            return False

        new_stock = self.products[product_id]["stock"] + quantity
        if new_stock < 0:
            return False

        self.products[product_id]["stock"] = new_stock
        return True

    def calculate_bulk_price(self, product_id, quantity):
        if product_id not in self.products:
            return -1

        price = self.products[product_id]["price"]
        # Apply volume discounts
        if quantity >= 100:
            discount = 0.20 # 20% off
        elif quantity >= 50:
            discount = 0.10 # 10% off
        elif quantity >= 10:
            discount = 0.05 # 5% off
        else:
            discount = 0

        return (price * quantity) * (1 - discount)

    def find_products_by_category(self, category):
        category = category.upper()
        return [p for p in self.products.values() if p["category"] == category]

    def get_inventory_worth(self):
        return sum(p["price"] * p["stock"] for p in self.products.values())

    def apply_seasonal_discount(self, category, percentage):
        if percentage < 0 or percentage > 100:
            return False

        category = category.upper()
        affected_count = 0
        for p in self.products.values():
            if p["category"] == category:
                p["price"] *= (1 - (percentage / 100))
                affected_count += 1
        return affected_count

from datetime import datetime, timedelta
import uuid

class PaymentProcessor:
    def __init__(self):
        self.transaction_log = []
        self.tax_rates = {
            "NY": 0.08875,
            "CA": 0.0725,
            "TX": 0.0625,
            "FL": 0.0600
        }

    def process_payment(self, amount: float, card_number: str) -> dict:
        """Process a payment and return the transaction details."""
        if amount <= 0:
            raise ValueError("Payment amount must be strictly positive")

        # Simple mock validation: Visa (4), Mastercard (5), Amex (3)
        if not (card_number.startswith("4") or card_number.startswith("5") or card_number.startswith("3")):
            return {"status": "FAILED", "reason": "Unsupported card type"}

        # Visa/MC are 16 digits, Amex is 15
        if card_number.startswith("3") and len(card_number) != 15:
            return {"status": "FAILED", "reason": "Invalid Amex length"}
        elif not card_number.startswith("3") and len(card_number) != 16:
            return {"status": "FAILED", "reason": "Invalid Visa/MC length"}

        transaction_id = str(uuid.uuid4())
        record = {
            "transaction_id": transaction_id,
            "amount": amount,
            "status": "SUCCESS",
            "timestamp": datetime.now()
        }
        self.transaction_log.append(record)
        return record

    def calculate_total_with_tax(self, base_amount: float, region_code: str) -> float:
        """Calculate the final amount including regional tax."""
        if base_amount <= 0:
            return 0.0

        rate = self.tax_rates.get(region_code.upper(), 0.0)
        tax = base_amount * rate
        return round(base_amount + tax, 2)

    def refund_payment(self, transaction_id: str) -> bool:
        """Refund an existing successful payment if within 30 days."""
        for record in self.transaction_log:
            if record["transaction_id"] == transaction_id and record["status"] == "SUCCESS":

                # Check if refund window has expired
                if datetime.now() - record["timestamp"] > timedelta(days=30):
                    return False

                record["status"] = "REFUNDED"
                return True

        return False

    def get_total_revenue(self) -> float:
        """Calculate total successful revenue."""
        return sum(
            record["amount"] 
            for record in self.transaction_log 
            if record["status"] == "SUCCESS"
        )

